/**
 * The downloaded 3D garment library (public/garment-library, built by `npm run assets:acquire`).
 * Every entry is a real model file with a verified licence; nothing here is generated by ModVerse.
 * Admins switch garments on or off through the `garment_library` platform setting (no code change, no schema change).
 */
import fs from "node:fs";
import path from "node:path";
import { eq } from "drizzle-orm";
import { getDb } from "@/lib/db/client";
import { platformSettings } from "@/lib/db/schema";

export interface LibraryGarment {
  id: string; name: string; audience: "men" | "women" | "unisex"; category: string; collection: string; path: string; glb: string;
  thumbnail: string | null; licence: string; creator: string; attribution: string; triangles: number; qualityLevel: "A" | "B" | "C"; hasTexture: boolean;
}
export interface LibraryManifest extends Record<string, unknown> {
  id: string; name: string; originalName: string; description: string;
  source: { pack: string; pageUrl: string; downloadUrl: string; creator: string; downloadedAt: string };
  licence: { id: string; commercialUse: boolean; attributionRequired: boolean; attribution: string };
  geometry: { vertices: number; triangles: number; uvCoverage: number; boundsCm: { width: number; height: number; depth: number } };
  materials: { baseColorTexture: boolean; normalTexture: boolean };
  rigging: string; sewingPatterns: boolean; manufacturing: string; customisation: string[]; sizes: string; tags: string[];
}

const DIR = path.join(process.cwd(), "public", "garment-library");
let cache: { mtime: number; garments: LibraryGarment[] } | null = null;

/** Catalogue entries whose GLB file is actually present on disk (an entry without its file is never listed). */
export function libraryIndex(): LibraryGarment[] {
  const file = path.join(DIR, "index.json");
  if (!fs.existsSync(file)) return [];
  const mtime = fs.statSync(file).mtimeMs;
  if (cache?.mtime === mtime) return cache.garments;
  const all = (JSON.parse(fs.readFileSync(file, "utf8")).garments ?? []) as LibraryGarment[];
  const garments = all.filter((g) => /^[a-z0-9-]+$/.test(g.id) && fs.existsSync(path.join(DIR, g.path, g.glb)));
  cache = { mtime, garments };
  return garments;
}

export function libraryManifest(g: LibraryGarment): LibraryManifest | null {
  try { return JSON.parse(fs.readFileSync(path.join(DIR, g.path, "manifest.json"), "utf8")); } catch { return null; }
}

export async function disabledGarments(): Promise<Set<string>> {
  const db = await getDb();
  const [row] = await db.select().from(platformSettings).where(eq(platformSettings.key, "garment_library"));
  const v = row?.value as { disabled?: unknown } | undefined;
  return new Set(Array.isArray(v?.disabled) ? v.disabled.filter((x): x is string => typeof x === "string") : []);
}

/** Garments customers can see: files present and not switched off by an admin. */
export async function visibleGarments(): Promise<LibraryGarment[]> {
  const off = await disabledGarments();
  return libraryIndex().filter((g) => !off.has(g.id));
}

export { COLLECTION_LABELS } from "./garment-library-labels";

